-- специально кривой скрипт с типичными косяками, мок должен найти все
-- гоняй: lua mock/run.lua mock/examples/broken.lua --keep-going

---@diagnostic disable: undefined-global

if not __UMBRELLA_MOCK then return {} end

local script = {}
local ui = {}

function script.OnScriptsLoaded()
    local tab = Menu.Create("Scripts", "Utility", "Broken")
    ui.enabled = tab:Switch("Включить", true)
end

function script.OnUpdte()
end

function script.OnUpdate()
    local hero = Heroes.GetLocal()

    local pos = NPC.GetPosition(hero)

    local hp = NPC.GetHealth(hero)

    local z = World.GetGroundZ(Entity.GetAbsOrigin(hero))

    local order = Enum.UnitOrder.DOTA_UNIT_ORDER_MOVE

    local player = Players.GetLocal()
    for _, npc in pairs(NPCs.GetAll()) do
        if NPC.IsControllableByPlayer(npc, Player.GetPlayerID(player)) and npc ~= hero then
            Player.PrepareUnitOrders(player, Enum.UnitOrder.DOTA_UNIT_ORDER_MOVE_TO_POSITION, nil,
                Entity.GetAbsOrigin(hero), nil, Enum.PlayerOrderIssuer.DOTA_ORDER_ISSUER_PASSED_UNIT_ONLY, npc)
        end
    end

    local blink = NPC.GetItem(hero, "item_blink")
    local ready = Ability.GetCooldown(blink) == 0
end

function script.OnDraw()
    local angle = math.atan2(1, 1)
end

return script

